// ===========================================================================
// CASAGENCIA · ASISTENTE DE WHATSAPP — CONFIGURACION COMUN
// ---------------------------------------------------------------------------
// Proyecto independiente del asistente telefonico: sus workflows llevan [WA] y
// no llaman nunca a los [TEL]. Comparten los MISMOS datos (el Google Sheet de
// la cartera y los calendarios de Carmen y Gisela), no el codigo en ejecucion.
//
// Se inyecta al principio de los nodos Code propios de WhatsApp.
// Editar aqui y volver a desplegar:  python3 build_whatsapp.py --deploy
// ===========================================================================
const ZONA = 'Europe/Madrid';

// --- Chatwoot (panel de conversaciones) -------------------------------------
const CHATWOOT_URL    = 'https://panel-casa-agencia.serversvisionarius.com';
const CHATWOOT_CUENTA = 1;   // "Casa Agencia Inmobiliaria"
const CHATWOOT_INBOX  = 1;   // inbox "WhatsApp" (whatsapp_cloud, +34 864 89 37 94)

// --- Meta · WhatsApp Cloud API ---------------------------------------------
// Linea +34 864 89 37 94 (Casa Agencia Inmobiliaria), verificada y conectada.
// El token NO va aqui: esta en la credencial "Meta WhatsApp Casagencia".
const META_API        = 'https://graph.facebook.com/v22.0';
const META_PHONE_ID   = '1254647111075735';
const META_WABA_ID    = '1791979752043585';

// Plantillas aprobadas. OJO con el idioma: bienvenida_alquiler y plantilla_aviso
// estan dadas de alta en INGLES ('en') aunque el texto sea en espanol. Meta
// rechaza el envio si el codigo de idioma no es exactamente el registrado.
// Las tres usan parametros por posicion: {{1}} y {{2}}.
const PLANTILLAS = {
  compra:   { nombre: 'bienvenida_compra',   idioma: 'es' },  // {{1}} nombre, {{2}} enlace del inmueble
  alquiler: { nombre: 'bienvenida_alquiler', idioma: 'en' },  // {{1}} nombre, {{2}} enlace del inmueble
  aviso:    { nombre: 'plantilla_aviso',     idioma: 'en' },  // {{1}} comercial, {{2}} el aviso (una linea)
};

// Texto exacto de cada plantilla, tal y como esta aprobada en Meta. Solo se usa
// para que en el panel se lea lo mismo que le ha llegado al cliente.
const TEXTO_PLANTILLA = {
  bienvenida_compra:
    'Hola *{{1}}*, soy Sara de Casa Agencia.\nHemos recibido tu solicitud de información por este inmueble de compra: {{2}}\n*Quieres visitar la vivienda?*',
  bienvenida_alquiler:
    'Hola *{{1}}*, soy Sara de Casa Agencia.\nHemos recibido tu solicitud de información por este inmueble de alquiler: {{2}}\n*Quieres visitar la vivienda?*',
  plantilla_aviso:
    'Hola *{{1}}*,\n*{{2}}*\nUn saludo. Tenga un buen día.',
};

// --- El equipo ---------------------------------------------------------------
// Mismo reparto que el telefono: la referencia manda.
const ASESORA_POR_PREFIJO = { BN: 'Carmen', OR: 'Carmen', CS: 'Gisela', VR: 'Gisela' };
const ASESORA_POR_MUNICIPIO = {
  'benicasim': 'Carmen', 'benicassim': 'Carmen', 'oropesa': 'Carmen', 'orpesa': 'Carmen',
  'torreblanca': 'Carmen', 'onda': 'Carmen', 'borriol': 'Carmen', 'vilafames': 'Carmen',
  'castellon': 'Gisela', 'castello': 'Gisela', 'vila-real': 'Gisela', 'villarreal': 'Gisela',
  'burriana': 'Gisela', 'borriana': 'Gisela', 'almazora': 'Gisela', 'almassora': 'Gisela',
  'alquerias': 'Gisela', 'alqueries': 'Gisela',
};
// Moviles a los que llega el aviso por WhatsApp (los mismos que usa el telefono
// para saber por que linea entra la llamada).
const EQUIPO = {
  Carmen:   { movil: '34654907386', email: 'carmen@casagencia.com' },
  Gisela:   { movil: '34690027772', email: 'gisela@casagencia.com' },
  Laurence: { movil: '34618724192', email: 'laurence@casagencia.com' },
};
const EMAIL_DIRECCION = 'paco@casagencia.com';   // copia por correo de todos los avisos

// --- Leads por correo ----------------------------------------------------------
const BUZON_LEADS = 'PENDIENTE@casagencia.com';   // PENDIENTE: el buzon donde entran
const PORTALES = [
  { nombre: 'Idealista',  de: /idealista\.com/i,   asunto: /idealista/i },
  { nombre: 'Fotocasa',   de: /fotocasa\.es/i,     asunto: /fotocasa/i },
  { nombre: 'Habitaclia', de: /habitaclia\.com/i,  asunto: /habitaclia/i },
  { nombre: 'Web',        de: /casagencia\.com/i,  asunto: /formulario|contacto/i },
];

// --- Etiquetas de Chatwoot ---------------------------------------------------
// Las mismas que Blue, creadas ya en el panel. Las tres primeras son el estado
// de la conversacion (solo una a la vez y nunca hacia atras); la cuarta se suma
// a la que haya y hace que el bot deje de contestar.
const ETIQUETAS = {
  bienvenida: '1-bienvenida_ia',   // la IA ha mandado la plantilla
  en_proceso: '2-en_proceso',      // el cliente ha contestado y la IA esta con el
  agendada:   '3-agendada_ia',     // visita agendada de verdad en el calendario
  intervenir: '4-intervenir',      // tiene que entrar una persona: la IA se calla
};
const ESTADOS = [ETIQUETAS.bienvenida, ETIQUETAS.en_proceso, ETIQUETAS.agendada];

// --- Tiempos -----------------------------------------------------------------
const BUFFER_SEGUNDOS = 60;         // se juntan los mensajes que el cliente manda seguidos
const RECORDATORIO_HORAS = 24;      // aviso al comercial antes de cada visita
// Antelacion minima para agendar desde WhatsApp. 0 = la que permita el horario.
const ANTELACION_MINIMA_HORAS = 0;

// Marca que llevan en la descripcion las visitas agendadas por WhatsApp. Con
// ella el recordatorio sabe cuales son suyas y no avisa de las del telefono.
const MARCA_ORIGEN = 'Origen: WhatsApp (Sara IA)';

// ---------------------------------------------------------------------------
// Utilidades
// ---------------------------------------------------------------------------
function normalizarTelefono(raw) {
  let s = String(raw ?? '').trim();
  const teniaMas = s.startsWith('+');
  s = s.replace(/\D/g, '');
  if (!teniaMas && s.startsWith('00')) s = s.slice(2);
  if (/^[6789]\d{8}$/.test(s)) s = '34' + s;
  return {
    e164: s ? '+' + s : '',
    wa_id: s,                                   // como lo quiere Meta: solo digitos
    nacional: s.startsWith('34') ? s.slice(2) : s,
    valido: s.length >= 8 && s.length <= 15,
  };
}

const sinAcentos = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

function prefijoDeReferencia(ref) {
  const m = String(ref ?? '').toUpperCase().match(/[A-Z]{2}/);
  return m ? m[0] : '';
}

// Asesora por referencia y, si no hay, por municipio. Si no hay ninguna, Laurence.
function resolverAsesora(ref, municipio) {
  const prefijo = prefijoDeReferencia(ref);
  let asesora = ASESORA_POR_PREFIJO[prefijo] || null;
  if (!asesora && municipio) {
    const m = sinAcentos(municipio);
    for (const [clave, quien] of Object.entries(ASESORA_POR_MUNICIPIO)) {
      if (m.includes(clave)) { asesora = quien; break; }
    }
  }
  const final = asesora || 'Laurence';
  return { prefijo, asesora, conocida: !!asesora, destinatario: final, ...EQUIPO[final] };
}

// Alquiler o compra. Mismo criterio que el telefono: lo dice la operacion o la
// referencia acaba en -A.
function esAlquiler(referencia, operacion) {
  const o = String(operacion ?? '').toLowerCase();
  if (o.includes('alquiler') || o.includes('traspaso') || o.includes('rent')) return true;
  if (o.includes('venta') || o.includes('compra')) return false;
  return /-A$/i.test(String(referencia ?? '').trim());
}

function detectarPortal(remitente, asunto) {
  for (const p of PORTALES) {
    if (p.de.test(String(remitente ?? '')) || p.asunto.test(String(asunto ?? ''))) return p.nombre;
  }
  return 'Otro';
}

// Meta no admite saltos de linea, tabuladores ni mas de 4 espacios seguidos
// dentro de un parametro de plantilla: si los hay, rechaza el envio entero.
function paramPlantilla(texto, max = 700) {
  return String(texto ?? '')
    .replace(/[\r\n\t]+/g, ' · ')
    .replace(/ {2,}/g, ' ')
    .trim()
    .slice(0, max) || '-';
}

// "2026-10-02" + "17:00" -> "jueves 2 de octubre a las 17:00"
function fechaLegible(fecha, hora) {
  const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
  const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto',
                 'septiembre', 'octubre', 'noviembre', 'diciembre'];
  const d = DateTime.fromFormat(String(fecha), 'yyyy-MM-dd', { zone: ZONA });
  if (!d.isValid) return `${fecha} ${hora || ''}`.trim();
  return `${DIAS[d.weekday - 1]} ${d.day} de ${MESES[d.month - 1]}` + (hora ? ` a las ${hora}` : '');
}


// ===========================================================================
// CARTERA · utilidades comunes de los nodos que leen el Google Sheet
// ---------------------------------------------------------------------------
// La hoja la rellena el [TEL] XMLCacheo desde el feed de eGO: WhatsApp solo la
// LEE. Columnas: ref, precio, tipo_transaccion, tipo_inmueble, municipio, zona,
// habitaciones, banos, superficie, caracteristicas, descripcion, imagen...
// La pestana "Direcciones" (ref, direccion) la rellena la agencia a mano.
// ===========================================================================
const MUNICIPIOS = [
  { valor: 'Almazora / Almassora',                       claves: ['almazora', 'almassora'] },
  { valor: 'Alquerías del Niño Perdido',                 claves: ['alquerias', 'alqueries'] },
  { valor: 'Benicasim / Benicàssim',                     claves: ['benicasim', 'benicassim', 'beni'] },
  { valor: 'Borriol',                                    claves: ['borriol'] },
  { valor: 'Burriana / Borriana',                        claves: ['burriana', 'borriana'] },
  { valor: 'Castellón de la Plana / Castelló de la Plana', claves: ['castellon', 'castello'] },
  { valor: 'Onda',                                       claves: ['onda'] },
  { valor: 'Oropesa del Mar / Orpesa',                   claves: ['oropesa', 'orpesa'] },
  { valor: 'Torreblanca',                                claves: ['torreblanca'] },
  { valor: 'Vilafamés',                                  claves: ['vilafames'] },
  { valor: 'Vila-real',                                  claves: ['vila-real', 'villarreal', 'vilareal', 'vila real'] },
];

function normalizarMunicipio(texto) {
  const t = sinAcentos(texto).trim();
  if (!t) return '';
  for (const m of MUNICIPIOS) if (m.claves.some(c => t.includes(c))) return m.valor;
  return '';
}

// Nombre corto para ensenar al cliente: "Castellón", no "Castellón de la Plana / Castelló..."
const municipioCorto = (v) => String(v ?? '').split(' / ')[0].replace(' de la Plana', '');

// Sinonimos de tipo: el cliente dice "casa" y en la hoja pone "Chalet" o "Villa".
const TIPOS = {
  piso:    ['piso', 'apartamento', 'atico', 'duplex', 'estudio', 'planta baja', 'flat'],
  casa:    ['casa', 'chalet', 'villa', 'adosad', 'bungalow', 'finca', 'unifamiliar'],
  atico:   ['atico'],
  local:   ['local', 'oficina', 'nave'],
  terreno: ['terreno', 'parcela', 'solar', 'suelo'],
  garaje:  ['garaje', 'parking', 'plaza'],
  trastero:['trastero'],
};
function casaTipo(pedido, tipoFila) {
  const p = sinAcentos(pedido).trim();
  if (!p) return true;
  const t = sinAcentos(tipoFila);
  const lista = TIPOS[p] || Object.values(TIPOS).find(l => l.some(x => p.includes(x))) || [p];
  return lista.some(x => t.includes(x));
}

const aNumero = (v) => {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').replace(/[^\d.,]/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : 0;
};

function limpiarFila(r) {
  return {
    ref: String(r.ref).trim(),
    precio: aNumero(r.precio),
    operacion: String(r.tipo_transaccion ?? '').toLowerCase().includes('alquil') ? 'alquiler' : 'venta',
    tipo: String(r.tipo_inmueble ?? '').trim() || 'Inmueble',
    municipio: String(r.municipio ?? '').trim(),
    zona: String(r.zona ?? '').trim(),
    habitaciones: Math.round(aNumero(r.habitaciones)),
    banos: Math.round(aNumero(r.banos)),
    superficie: Math.round(aNumero(r.superficie)),
    caracteristicas: String(r.caracteristicas ?? '').trim(),
    descripcion: String(r.descripcion ?? '').replace(/\s+/g, ' ').trim(),
    imagen: String(r.imagen ?? '').trim(),
  };
}

function leerCartera(nodo) {
  return $(nodo).all().map(i => i.json).filter(r => r && r.ref).map(limpiarFila);
}

function leerDirecciones(nodo) {
  const dirs = {};
  try {
    for (const it of $(nodo).all()) {
      const j = (it && it.json) ? it.json : {};
      if (j.ref && j.direccion) dirs[String(j.ref).trim().toUpperCase()] = String(j.direccion).trim();
    }
  } catch (e) { /* sin pestana de direcciones: se sigue sin ellas */ }
  return dirs;
}

const euros = (n, operacion) => n
  ? n.toLocaleString('es-ES', { maximumFractionDigits: 0 }) + ' €' + (operacion === 'alquiler' ? '/mes' : '')
  : 'precio a consultar';

// Todo el texto donde buscar extras ("piscina", "vistas al mar"...)
const textoBuscable = (r) => sinAcentos(`${r.tipo} ${r.zona} ${r.caracteristicas} ${r.descripcion}`);

// Una linea por inmueble, para listados
function tarjeta(r, dirs) {
  const partes = [
    `${r.tipo} en ${r.zona ? r.zona + ', ' : ''}${municipioCorto(r.municipio)}`,
    r.habitaciones ? `${r.habitaciones} hab.` : '',
    r.banos ? `${r.banos} baños` : '',
    r.superficie ? `${r.superficie} m²` : '',
    euros(r.precio, r.operacion),
  ].filter(Boolean);
  const dir = dirs && dirs[r.ref.toUpperCase()];
  const destacado = r.caracteristicas.split(',').map(s => s.trim()).filter(Boolean).slice(0, 3).join(', ');
  return `[${r.ref}] ${partes.join(' · ')}` + (dir ? ` · ${dir}` : '')
    + (destacado ? ` · ${destacado}` : '');
}

// Busca una referencia con la misma tolerancia que el telefono: exacta, luego
// prefijo + numero (se ignoran las letras intermedias y la final), luego solo numero.
function buscarReferencia(filas, texto) {
  const norm = s => String(s ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const partes = s => {
    const n = norm(s);
    const pref = (n.match(/^[A-Z]{2}/) || [''])[0];
    const nums = (n.match(/\d+/g) || []).sort((a, b) => b.length - a.length);
    return { n, pref, num: nums[0] || '' };
  };
  const q = partes(texto);
  if (!q.n) return { filas: [], parecidas: [] };
  const idx = filas.map(r => ({ r, p: partes(r.ref) }));
  let m = idx.filter(x => x.p.n === q.n);
  if (!m.length && q.pref && q.num) m = idx.filter(x => x.p.pref === q.pref && x.p.num === q.num);
  if (!m.length && q.num) m = idx.filter(x => x.p.num === q.num);
  const parecidas = (!m.length && q.pref && q.num)
    ? idx.filter(x => x.p.pref === q.pref && x.p.num.length === q.num.length &&
        [...x.p.num].filter((c, i) => c !== q.num[i]).length === 1).map(x => x.r.ref).slice(0, 3)
    : [];
  return { filas: m.map(x => x.r), parecidas };
}


// [WA][SUB] buscarPorReferencia · FichaCompleta
// Devuelve TODO lo que sabemos del inmueble, para que Sara pueda resolver
// cualquier duda sin inventar: precio, superficie, habitaciones, banos,
// caracteristicas, direccion (si la agencia la ha puesto) y la descripcion
// entera del anuncio.
const pedido = String($('Start').first().json.referencia ?? '').trim();
const filas = leerCartera('LeerCartera');
const dirs = leerDirecciones('LeerDirecciones');
const salida = (texto, extra = {}) => [{ json: { respuesta: texto, ...extra } }];

// Sin cartera no es que la referencia no exista: es una incidencia.
if (!filas.length) {
  return salida('No he podido consultar la cartera por un problema tecnico. NO le digas al cliente que ' +
    'el inmueble no existe: dile que lo compruebas con la asesora y usa avisarEquipo.', { encontrado: false });
}
if (!pedido) {
  return salida('No me has pasado ninguna referencia. Si la tienes en los datos del cliente, usala.', { encontrado: false });
}

const { filas: encontradas, parecidas } = buscarReferencia(filas, pedido);

if (!encontradas.length) {
  if (parecidas.length) {
    return salida(`No localizo ${pedido}. En la cartera hay referencias parecidas: ${parecidas.join(', ')}. ` +
      'Pregunta al cliente si puede ser alguna de esas.', { encontrado: false, parecidas });
  }
  return salida(`No localizo la referencia ${pedido} en la cartera actual. Puede que ya se haya vendido o ` +
    'alquilado y siga publicada en el portal. No digas que no existe: diselo con tacto, ofrecele ' +
    'inmuebles parecidos con recomendarSimilares o buscarInmuebles, o avisa al equipo.', { encontrado: false });
}

const ficha = (r) => {
  const dir = dirs[r.ref.toUpperCase()];
  const lineas = [
    `Referencia: ${r.ref}`,
    `Operacion: ${r.operacion === 'alquiler' ? 'ALQUILER (no se agenda: se cualifica y se pasa al equipo)' : 'VENTA'}`,
    `Tipo: ${r.tipo}`,
    `Municipio: ${municipioCorto(r.municipio)}`,
    r.zona ? `Zona: ${r.zona}` : '',
    `Direccion: ${dir || 'no consta (no la deduzcas; si la pide, ofrece que se la confirme la asesora)'}`,
    `Precio: ${euros(r.precio, r.operacion)}`,
    r.superficie ? `Superficie: ${r.superficie} m²` : '',
    r.habitaciones ? `Habitaciones: ${r.habitaciones}` : '',
    r.banos ? `Baños: ${r.banos}` : '',
    r.caracteristicas ? `Caracteristicas: ${r.caracteristicas}` : '',
    r.descripcion ? `Descripcion del anuncio: ${r.descripcion}` : '',
    `Asesora: ${resolverAsesora(r.ref, r.municipio).destinatario}`,
  ].filter(Boolean);
  return lineas.join('\n');
};

if (encontradas.length === 1) {
  const r = encontradas[0];
  return salida('Ficha del inmueble (datos reales de la cartera; lo que no este aqui, no lo sabes):\n' + ficha(r),
    { encontrado: true, referencia: r.ref, operacion: r.operacion });
}

// Varias con el mismo numero: que el cliente diga cual
return salida(`Hay ${encontradas.length} inmuebles que encajan con ${pedido}. Preguntale al cliente algun ` +
  'detalle que los distinga:\n' + encontradas.slice(0, 3).map(r => '- ' + tarjeta(r, dirs)).join('\n'),
  { encontrado: true, varios: true });
